msg._d = msg._d || {};
try { msg._d.soc = msg.payload[0].v; } catch(e) { msg._d.soc = null; }
return msg;

// 30d Durchschnitt bereits berechnet in store 22:00 Node
// nichts tun hier

const d = msg._d;
const CAPACITY = 10.0; // Beispielwert, im Original anlagenspezifisch
const SOC_MIN  = 10;

const wr_eigenverbrauch = (d.daily_pv_kwh !== null && d.daily_load_kwh !== null && d.daily_bat_in !== null && d.daily_bat_out !== null)
    ? d.daily_pv_kwh - d.daily_load_kwh - d.daily_bat_in + Math.abs(d.daily_bat_out)
    : null;
const avail_kwh = d.soc !== null ? ((d.soc - SOC_MIN) / 100 * CAPACITY) : null;
const net_kw    = (d.pv_w !== null && d.load_w !== null) ? (d.pv_w - d.load_w) / 1000 : null;

let range_h = null, range_label = '∞', range_status = 'infinite';
if (net_kw !== null && avail_kwh !== null) {
    if (net_kw >= 0) {
        range_label = '∞'; range_status = 'infinite';
    } else {
        range_h = avail_kwh / Math.abs(net_kw);
        if      (range_h > 72) { range_label = '> 72 h';                        range_status = 'ok';   }
        else if (range_h >= 8) { range_label = range_h.toFixed(1) + ' h';       range_status = 'ok';   }
        else if (range_h >= 3) { range_label = range_h.toFixed(1) + ' h';       range_status = 'warn'; }
        else if (range_h >= 1) { range_label = range_h.toFixed(1) + ' h';       range_status = 'crit'; }
        else                   { range_label = Math.round(range_h*60) + ' min';  range_status = 'crit'; }
    }
}
// Smarte Reichweite mit Forecast
const forecast_kwh = d.forecast_tomorrow_kwh || 0;
const total_avail  = (avail_kwh || 0) + forecast_kwh;
const avg_h        = d.avg_30d_kwh ? d.avg_30d_kwh / 24 : null;

let smart_range_label  = range_label;
let smart_range_status = range_status;

if (avg_h && total_avail >= (d.avg_30d_kwh || 0)) {
    smart_range_label  = '∞';
    smart_range_status = 'infinite';
} else if (avg_h) {
    const sh = total_avail / avg_h;
    if      (sh > 72) { smart_range_label = '> 72 h';                    smart_range_status = 'ok';   }
    else if (sh >= 8) { smart_range_label = sh.toFixed(1) + ' h';        smart_range_status = 'ok';   }
    else if (sh >= 3) { smart_range_label = sh.toFixed(1) + ' h';        smart_range_status = 'warn'; }
    else if (sh >= 1) { smart_range_label = sh.toFixed(1) + ' h';        smart_range_status = 'crit'; }
    else              { smart_range_label = Math.round(sh*60) + ' min';  smart_range_status = 'crit'; }
}

let delta_pct = null;
if (d.avg_30d_kwh && d.daily_load_kwh) {
    delta_pct = ((d.daily_load_kwh - d.avg_30d_kwh) / d.avg_30d_kwh) * 100;
}

let bat_direction = 'idle';
if (d.bat_w !== null) {
    if      (d.bat_w > 50)  bat_direction = 'charging';
    else if (d.bat_w < -50) bat_direction = 'discharging';
}


// ============================================================
// SPLIT: Nacht (22-06) / Tag (06-17) / Abend (17-22)
// ============================================================
const anchor_06 = d.anchor_06;  // kWh-Zählerstand um 06:00
const anchor_17 = d.anchor_17;  // kWh-Zählerstand um 17:00
const anchor_22 = d.anchor_22;  // kWh-Zählerstand um 22:00 GESTERN
const load_now  = d.daily_load_kwh; // aktueller Tagesstand

// Nacht = 00:00 bis 06:00 (Zähler startet um Mitternacht bei 0)
// anchor_06 ist direkt der kumulierte Nachtverbrauch
let kwh_nacht  = anchor_06 !== null ? Math.max(0, anchor_06) : null;
// Tag   = von 06:00 bis 17:00
let kwh_tag    = (anchor_17 !== null && anchor_06 !== null) ? Math.max(0, anchor_17 - anchor_06) : null;
// Abend = von 17:00 bis jetzt (oder bis 22:00 wenn vorbei)
let kwh_abend  = (load_now !== null && anchor_17 !== null) ? Math.max(0, load_now - anchor_17) : null;

// Gestriger Tagesverbrauch = vorletzter Wert im avg_payload
let yesterday_kwh = null;
try {
    const ap = (d.avg_payload || []).filter(r => r.v > 1);
    yesterday_kwh = ap.length >= 2 ? ap[ap.length - 2].v : null;
} catch(e) {}

let delta_yesterday_pct = null;
if (yesterday_kwh !== null && d.avg_30d_kwh) {
    delta_yesterday_pct = ((yesterday_kwh - d.avg_30d_kwh) / d.avg_30d_kwh) * 100;
}
// ============================================================
// QUOTEN: Autarkie + Eigenverbrauch — Heute / Woche / Jahreszeit / Jahr
// ============================================================
// Quoten aus flow context (alle 30min aktualisiert)
const pv_quoten = flow.get('pv_quoten') || {};
const q_heute  = quoten(d.daily_load_kwh, d.daily_pv_kwh, d.daily_grid_kwh);
function quoten(load, pv, grid) {
    if (!load || !pv || grid === null || grid === undefined) return { autarkie: null, eigenverbrauch: null };
    return {
        autarkie:       Math.round(Math.max(0, Math.min(100, (load - grid) / load * 100)) * 10) / 10,
        eigenverbrauch: Math.round(Math.max(0, Math.min(100, load / pv * 100)) * 10) / 10
    };
}
msg.payload = {
    smart_range_label:  smart_range_label,
    smart_range_status: smart_range_status,
    forecast_tomorrow_kwh: d.forecast_tomorrow_kwh !== null ? Math.round(d.forecast_tomorrow_kwh * 10) / 10 : null,
    autarkie_heute:        q_heute.autarkie,
    eigenverbrauch_heute:  q_heute.eigenverbrauch,
    autarkie_woche:        pv_quoten.woche  ? pv_quoten.woche.aut  : null,
    eigenverbrauch_woche:  pv_quoten.woche  ? pv_quoten.woche.ev   : null,
    autarkie_season:       pv_quoten.season ? pv_quoten.season.aut : null,
    eigenverbrauch_season: pv_quoten.season ? pv_quoten.season.ev  : null,
    autarkie_jahr:         pv_quoten.jahr   ? pv_quoten.jahr.aut   : null,
    eigenverbrauch_jahr:   pv_quoten.jahr   ? pv_quoten.jahr.ev    : null,
    wr_eigenverbrauch: wr_eigenverbrauch !== null ? Math.round(wr_eigenverbrauch * 10) / 10 : null,
    ts:             new Date().toISOString(),
    soc:            d.soc,
    avail_kwh:      avail_kwh !== null ? Math.round(avail_kwh * 10) / 10 : null,
    pv_w:           d.pv_w,
    load_w:         d.load_w,
    bat_w:          d.bat_w,
    bat_direction:  bat_direction,
    forecast_w:     d.forecast_w,
    net_kw:         net_kw !== null ? Math.round(net_kw * 100) / 100 : null,
    range_h:        range_h !== null ? Math.round(range_h * 10) / 10 : null,
    range_label:    range_label,
    range_status:   range_status,
    daily_pv_kwh:   d.daily_pv_kwh,
    daily_load_kwh: d.daily_load_kwh,
    daily_grid_kwh: d.daily_grid_kwh,
    avg_30d_kwh:    d.avg_30d_kwh !== null ? Math.round(d.avg_30d_kwh * 10) / 10 : null,
    delta_pct:          delta_pct !== null ? Math.round(delta_pct * 10) / 10 : null,
    kwh_nacht:          kwh_nacht  !== null ? Math.round(kwh_nacht  * 10) / 10 : null,
    kwh_tag:            kwh_tag    !== null ? Math.round(kwh_tag    * 10) / 10 : null,
    kwh_abend:          kwh_abend  !== null ? Math.round(kwh_abend  * 10) / 10 : null,
    yesterday_kwh:      yesterday_kwh !== null ? Math.round(yesterday_kwh * 10) / 10 : null,
    delta_yesterday_pct: delta_yesterday_pct !== null ? Math.round(delta_yesterday_pct * 10) / 10 : null
};

msg.statusCode = 200;
msg.headers = { 'Content-Type': 'application/json', 'Access-Control-Allow-Origin': '*' };
return msg;

msg._d = msg._d || {};
const now = new Date();
const pad = s => String(s).padStart(2,'0');
const dateStr = now.getUTCFullYear() + '-' + pad(now.getUTCMonth()+1) + '-' + pad(now.getUTCDate());

// Berlin Sommerzeit = UTC+2
// 06:00 Berlin = 04:00 UTC → Fenster ±15min
// 17:00 Berlin = 15:00 UTC → Fenster ±15min
// 22:00 Berlin = 20:00 UTC → Fenster ±15min
flow.set('t06_from',  dateStr + 'T03:45:00Z');
flow.set('t06_to',    dateStr + 'T04:15:00Z');
flow.set('t17_from',  dateStr + 'T14:45:00Z');
flow.set('t17_to',    dateStr + 'T15:15:00Z');
flow.set('t22_from',  dateStr + 'T19:45:00Z');
flow.set('t22_to',    dateStr + 'T20:15:00Z');

msg._d.avg_payload = msg.payload;

// Query für Ankerpunkt 06:00
const f06 = flow.get('t06_from'), t06 = flow.get('t06_to');
msg.query = 'SELECT first("value") AS "v" FROM "iobroker"."autogen"."javascript.0.SolarDaily.daily.load_consumption" WHERE time >= \'' + f06 + '\' AND time <= \'' + t06 + '\'';
return msg;

try { msg._d.anchor_06 = msg.payload[0] ? msg.payload[0].v : null; } catch(e) { msg._d.anchor_06 = null; }
// Setze Query für nächsten Node
const f = flow.get('t17_from'), t = flow.get('t17_to');
msg.query = 'SELECT first("value") AS "v" FROM "iobroker"."autogen"."javascript.0.SolarDaily.daily.load_consumption" WHERE time >= \'' + f + '\' AND time <= \'' + t + '\'';
return msg;

try { msg._d.anchor_17 = msg.payload[0] ? msg.payload[0].v : null; } catch(e) { msg._d.anchor_17 = null; }
const f = flow.get('t22_from'), t = flow.get('t22_to');
msg.query = 'SELECT first("value") AS "v" FROM "iobroker"."autogen"."javascript.0.SolarDaily.daily.load_consumption" WHERE time >= \'' + f + '\' AND time <= \'' + t + '\'';
return msg;

// anchor_22: null wenn noch nicht erreicht (vor 22:00 Uhr)
try { msg._d.anchor_22 = msg.payload[0] ? msg.payload[0].v : null; } catch(e) { msg._d.anchor_22 = null; }

// 30d Durchschnitt aus avg_payload
try {
    const raw = msg._d.avg_payload || [];
    node.warn('avg_payload length: ' + raw.length);
    const vals = raw
        .filter(row => row.v !== null && row.v > 1)
        .map(row => row.v);
    const last30 = vals.slice(-30);
    msg._d.avg_30d_kwh = last30.length > 0
        ? last30.reduce((a,b) => a+b, 0) / last30.length
        : null;
    node.warn('avg_30d_kwh: ' + msg._d.avg_30d_kwh);
} catch(e) {
    node.warn('avg Fehler: ' + e.message);
    msg._d.avg_30d_kwh = null;
}

return msg;

msg._q = {};
try {
    const vals = msg.payload.filter(r => r.v > 1).map(r => r.v);
    msg._q.week_load = vals.slice(-7).reduce((a,b)=>a+b,0);
} catch(e) { msg._q.week_load = null; }
return msg;

try {
    const vals = msg.payload.filter(r => r.v > 1).map(r => r.v);
    msg._q.week_pv = vals.slice(-7).reduce((a,b)=>a+b,0);
} catch(e) { msg._q.week_pv = null; }
return msg;

try {
    const vals = msg.payload.filter(r => r.v >= 0).map(r => r.v);
    msg._q.week_grid = vals.slice(-7).reduce((a,b)=>a+b,0);
} catch(e) { msg._q.week_grid = null; }
return msg;

try {
    const now = new Date();
    const month = now.getUTCMonth();
    const qStart = [0,0,0,3,3,3,6,6,6,9,9,9][month];
    const cutoff = new Date(Date.UTC(now.getUTCFullYear(), qStart, 1, 22, 0, 0));
    const vals = msg.payload.filter(r => r.v > 1 && new Date(r.time) >= cutoff).map(r => r.v);
    msg._q.season_load = vals.length > 0 ? vals.reduce((a,b)=>a+b,0) : null;
} catch(e) { msg._q.season_load = null; }
return msg;

try {
    const now = new Date();
    const month = now.getUTCMonth();
    const qStart = [0,0,0,3,3,3,6,6,6,9,9,9][month];
    const cutoff = new Date(Date.UTC(now.getUTCFullYear(), qStart, 1, 22, 0, 0));
    const vals = msg.payload.filter(r => r.v > 1 && new Date(r.time) >= cutoff).map(r => r.v);
    msg._q.season_pv = vals.length > 0 ? vals.reduce((a,b)=>a+b,0) : null;
} catch(e) { msg._q.season_pv = null; }
return msg;

try {
    const now = new Date();
    const month = now.getUTCMonth();
    const qStart = [0,0,0,3,3,3,6,6,6,9,9,9][month];
    const cutoff = new Date(Date.UTC(now.getUTCFullYear(), qStart, 1, 22, 0, 0));
    const vals = msg.payload.filter(r => r.v >= 0 && new Date(r.time) >= cutoff).map(r => r.v);
    msg._q.season_grid = vals.length > 0 ? vals.reduce((a,b)=>a+b,0) : null;
} catch(e) { msg._q.season_grid = null; }
return msg;

try {
    const now = new Date();
    const cutoff = new Date(Date.UTC(now.getUTCFullYear(), 0, 1, 22, 0, 0));
    const vals = msg.payload.filter(r => r.v > 1 && new Date(r.time) >= cutoff).map(r => r.v);
    msg._q.year_load = vals.length > 0 ? vals.reduce((a,b)=>a+b,0) : null;
} catch(e) { msg._q.year_load = null; }
return msg;

try {
    const now = new Date();
    const cutoff = new Date(Date.UTC(now.getUTCFullYear(), 0, 1, 22, 0, 0));
    const vals = msg.payload.filter(r => r.v > 1 && new Date(r.time) >= cutoff).map(r => r.v);
    msg._q.year_pv = vals.length > 0 ? vals.reduce((a,b)=>a+b,0) : null;
} catch(e) { msg._q.year_pv = null; }
return msg;

try {
    const now = new Date();
    const cutoff = new Date(Date.UTC(now.getUTCFullYear(), 0, 1, 22, 0, 0));
    const vals = msg.payload.filter(r => r.v >= 0 && new Date(r.time) >= cutoff).map(r => r.v);
    msg._q.year_grid = vals.length > 0 ? vals.reduce((a,b)=>a+b,0) : null;
} catch(e) { msg._q.year_grid = null; }

// Quoten berechnen und in flow context speichern
function quot(load, pv, grid) {
    if (!load || !pv || grid === null || grid === undefined) return { aut: null, ev: null };
    return {
        aut: Math.round(Math.max(0, Math.min(100, (load - grid) / load * 100)) * 10) / 10,
        ev:  Math.round(Math.max(0, Math.min(100, load / pv * 100)) * 10) / 10
    };
}
node.warn(JSON.stringify(msg._q))
const q = msg._q;
const quoten = {
    woche:  quot(q.week_load,   q.week_pv,   q.week_grid),
    season: quot(q.season_load, q.season_pv, q.season_grid),
    jahr:   quot(q.year_load,   q.year_pv,   q.year_grid),
    ts:     new Date().toISOString()
};

flow.set('pv_quoten', quoten);
node.warn('Quoten gespeichert: ' + JSON.stringify(quoten));
return msg;

msg._d = msg._d || {};
try { msg._d.forecast_tomorrow_kwh = msg.payload[0].v / 1000; } catch(e) { msg._d.forecast_tomorrow_kwh = null; }
return msg;

msg._d = msg._d || {};
try { msg._d.forecast_tomorrow_kwh = msg.payload[0].v / 1000; } catch(e) { msg._d.forecast_tomorrow_kwh = null; }
return msg;
